package com.ethk3.novaonepro;
import java.io.*;import java.nio.file.*;import org.junit.Test;import static org.junit.Assert.*;
public final class RepairStorageCensusR30Test {
 @Test public void backupSnapshotAndProtectedModelAreMeasuredOnceWithoutCopyingOrDeleting()throws Exception{
  Path root=Files.createTempDirectory("r30-storage-");try{String[] paths={"databases/main.db","databases/main.db.bak","files/r981_reports/jobs/a/snapshot.db","files/model-bundles-r929/model.bin"};long total=0;for(int i=0;i<paths.length;i++){File f=root.resolve(paths[i]).toFile();assertTrue(f.getParentFile().isDirectory()||f.getParentFile().mkdirs());try(RandomAccessFile file=new RandomAccessFile(f,"rw")){file.setLength(1024L*(i+1));}total+=f.length();}StorageCensusSU2.Census c=StorageCensusSU2.measure(root.toFile());assertEquals(total,c.total);assertEquals(total,c.bytes.values().stream().mapToLong(Long::longValue).sum());assertEquals(total,c.detailBytes.values().stream().mapToLong(Long::longValue).sum());assertFalse(c.truncated);assertTrue(c.sampleFinishedAt>=c.sampleStartedAt);assertEquals(2048L,(long)c.detailBytes.get("OLD_BACKUP_PROTECTED_UNTIL_RECOVERY_PROOF"));assertEquals(3072L,(long)c.detailBytes.get("REPORT_OR_RETENTION_SNAPSHOT"));assertTrue(c.line().contains("REPORT_SNAPSHOT:immutable-report-job-reference"));for(String p:paths)assertTrue(Files.isRegularFile(root.resolve(p)));}finally{try(java.util.stream.Stream<Path> all=Files.walk(root)){all.sorted(java.util.Comparator.reverseOrder()).forEach(p->p.toFile().delete());}}
 }
 @Test public void depthAndSymlinkCannotSilentlyReportComplete()throws Exception{Path root=Files.createTempDirectory("r30-storage-depth-");try{Path deep=root;for(int i=0;i<15;i++)deep=Files.createDirectories(deep.resolve("d"));Files.write(deep.resolve("hidden"),new byte[]{1});Files.createSymbolicLink(root.resolve("outside"),root.resolve("d"));StorageCensusSU2.Census c=StorageCensusSU2.measure(root.toFile());assertTrue(c.truncated);assertTrue(c.incompleteReasons.contains("DEPTH_BUDGET_12"));assertTrue(c.incompleteReasons.contains("SYMLINK_NOT_FOLLOWED"));assertTrue(c.largest.size()<=8);}finally{try(java.util.stream.Stream<Path> all=Files.walk(root)){all.sorted(java.util.Comparator.reverseOrder()).forEach(p->p.toFile().delete());}}}
}
